import { inject, Injectable } from "@angular/core";
import { SuperService } from "./super.service";
import { Tramite } from "../models/tramite";
import { LocalStorageService } from "../services/localStorage/local-storage.service";

@Injectable({
    providedIn: 'root'
})
export class TramiteService extends SuperService<Tramite> {
    protected model = 'tramites';
    protected columns: (keyof Tramite)[] = [
        'tipo',
        'empresa_id',
        'empresa_vinculada_id',
        'proyecto_inversion_id',
        'usuario_id',
        'deleted_at',
        'created_at',
        'updated_at'
    ];
    private localStorageService = inject(LocalStorageService);

    public async usuarioLogeadoTieneTramite(){
        const user = this.localStorageService.getUser();

        if(!user || user.user.user_type !== 'EXTERNO'){
            return false;
        }

        const tramites = await this.all({ usuario_id: user.user.id });

        return tramites.length > 0;
    }

    public async getCurrentTramite(withRelations: string[]=[]){
        const user = this.localStorageService.getUser();

        if(!user || user.user.user_type !== 'EXTERNO'){
            return;
        }

        const tramites = await this.all({
            conditionals: { usuario_id: user.user.id },
            relations: withRelations,
            loader: false,
        });

        return tramites[0];
    }
}
